def hier():
    b=bx(160,5,200,38,'Companies')+bx(5,90,180,38,'Invoice')+bx(5,165,180,38,'Payments')+bx(250,60,170,38,'Contacts')
    b+=bx(170,120,110,38,'Letters')+bx(300,120,110,38,'Faxes')+bx(430,120,110,38,'Emails')
    b+=ln(260,43,260,50)+ln(95,60,260,50)+ln(95,60,95,90)+arr(95,90)+ln(360,50,360,60)+ln(335,50,335,60)+ln(260,50,335,50)+ln(335,60,335,60)
    b+=ln(95,128,95,165)+arr(95,165)+ln(335,98,225,120)+arr(225,120)+ln(335,98,355,120)+arr(355,120)+ln(335,98,485,120)+arr(485,120)
    return svg(560,215,'Hierarchical database model: Companies with children Invoice and Contacts, Invoice with Payments, Contacts with Letters, Faxes and Emails',b)
def netw():
    b=bx(170,5,150,36,'Store')+bx(20,90,150,36,'Customer')+bx(200,90,150,36,'Manager')+bx(380,90,150,36,'Salesman')+bx(100,170,150,36,'Order')+bx(300,170,150,36,'Items')
